#!/usr/bin/env node
// Synthesizes the background music for the demo video: 120 BPM, a restrained electronic beat. All generated by code, so there is no copyright issue.
// Usage: node docs/demo/music.mjs <output.wav> <total seconds> <cut seconds, comma-separated>
// Each cut gets a short rising noise sweep and an accent beat; the shot changes line up with them.
import { writeFileSync } from 'node:fs';

const [out, totalArg, cutsArg = ''] = process.argv.slice(2);
if (!out || !totalArg) {
  process.stderr.write('Usage: node docs/demo/music.mjs <output.wav> <total seconds> <cut seconds, comma-separated>\n');
  process.exit(2);
}
const SR = 44100;
const BPM = 120;
const BEAT = 60 / BPM;
const TOTAL = Number(totalArg);
const CUTS = cutsArg.split(',').filter(Boolean).map(Number);
const N = Math.ceil(TOTAL * SR);
const L = new Float32Array(N);
const R = new Float32Array(N);

// Deterministic pseudo-random numbers, so every run produces exactly the same music.
let seed = 7;
const rand = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296) * 2 - 1;

const add = (t0, dur, fn, pan = 0) => {
  const s0 = Math.floor(t0 * SR);
  const len = Math.floor(dur * SR);
  for (let i = 0; i < len && s0 + i < N; i++) {
    const v = fn(i / SR);
    L[s0 + i] += v * (1 - pan) * 0.5;
    R[s0 + i] += v * (1 + pan) * 0.5;
  }
};

const midi = (n) => 440 * 2 ** ((n - 69) / 12);

// Chord progression (one per bar): Am9 → Fmaj7 → C/E → G6
const CHORDS = [[57, 60, 64, 67, 71], [53, 57, 60, 64, 69], [52, 55, 60, 64, 67], [55, 59, 62, 64, 69]];
const ROOTS = [45, 41, 40, 43];

const kick = (t) => {
  const f = 45 + 80 * Math.exp(-t * 30);
  return Math.sin(2 * Math.PI * f * t - 2 * Math.exp(-t * 30)) * Math.exp(-t * 7) * 0.9;
};
const hat = () => {
  let prev = 0;
  return (t) => {
    const n = rand();
    const hp = n - prev;
    prev = n;
    return hp * Math.exp(-t * 60) * 0.12;
  };
};
const clap = () => (t) => rand() * Math.exp(-t * 22) * 0.22;
const pad = (notes) => (t) => {
  const env = Math.min(1, t / 0.35) * Math.min(1, (2 * BEAT * 4 - t) / 0.4);
  return notes.reduce((s, n) => {
    const f = midi(n);
    return s + (Math.sin(2 * Math.PI * f * t) + 0.25 * Math.sin(2 * Math.PI * f * 2.003 * t) + 0.12 * Math.sin(2 * Math.PI * f * 0.997 * t)) / notes.length;
  }, 0) * env * 0.16;
};
const bass = (n) => (t) => {
  const f = midi(n);
  const env = Math.min(1, t / 0.01) * Math.exp(-t * 3);
  return (Math.sin(2 * Math.PI * f * t) + 0.3 * Math.sin(2 * Math.PI * 2 * f * t)) * env * 0.35;
};
const pluck = (n) => (t) => {
  const f = midi(n);
  return (Math.sin(2 * Math.PI * f * t) + 0.4 * Math.sin(2 * Math.PI * 3 * f * t) * Math.exp(-t * 12)) * Math.exp(-t * 6) * 0.09;
};
const riser = (dur) => (t) => rand() * (t / dur) ** 2 * 0.18;

const bars = Math.ceil(TOTAL / (BEAT * 4));
const intro = 2;   // the first 2 bars have only the pad and a light hi-hat
for (let b = 0; b < bars; b++) {
  const t0 = b * BEAT * 4;
  const chord = b % 4;
  add(t0, BEAT * 8, pad(CHORDS[chord]), 0);
  for (let s = 0; s < 8; s++) {
    const ts = t0 + s * BEAT / 2;
    if (ts >= TOTAL) break;
    add(ts, 0.08, hat(), s % 2 ? 0.4 : -0.4);
    if (b >= intro) {
      if (s % 2 === 0) add(ts, 0.45, bass(ROOTS[chord] + (s === 6 ? 7 : 0)), 0);
      add(ts, 0.4, pluck(CHORDS[chord][[0, 2, 4, 3, 1, 2, 4, 3][s]] + 12), s % 2 ? 0.5 : -0.5);
    }
  }
  for (let q = 0; q < 4; q++) {
    const tq = t0 + q * BEAT;
    if (tq >= TOTAL) break;
    if (b >= intro || q === 0) add(tq, 0.5, kick, 0);
    if (b >= intro && (q === 1 || q === 3)) add(tq, 0.3, clap(), 0);
  }
}
for (const c of CUTS) {
  if (c >= 0.5) add(c - 0.5, 0.5, riser(0.5), 0);
  add(c, 0.5, kick, 0);
}

// Simple reverb: two feedback delays, offset left and right.
const delay = (buf, ms, fb, mix) => {
  const d = Math.floor((ms / 1000) * SR);
  for (let i = d; i < buf.length; i++) buf[i] += buf[i - d] * fb * mix;
};
delay(L, 187, 0.35, 0.5);
delay(R, 211, 0.35, 0.5);

// Fade in and out + soft limiting + normalization.
let peak = 0;
for (let i = 0; i < N; i++) {
  const t = i / SR;
  const fade = Math.min(1, t / 0.3) * Math.min(1, (TOTAL - t) / 1.2);
  L[i] = Math.tanh(L[i] * 1.2) * fade;
  R[i] = Math.tanh(R[i] * 1.2) * fade;
  peak = Math.max(peak, Math.abs(L[i]), Math.abs(R[i]));
}
const gain = 0.85 / (peak || 1);
const pcm = Buffer.alloc(44 + N * 4);
pcm.write('RIFF', 0); pcm.writeUInt32LE(36 + N * 4, 4); pcm.write('WAVE', 8);
pcm.write('fmt ', 12); pcm.writeUInt32LE(16, 16); pcm.writeUInt16LE(1, 20); pcm.writeUInt16LE(2, 22);
pcm.writeUInt32LE(SR, 24); pcm.writeUInt32LE(SR * 4, 28); pcm.writeUInt16LE(4, 32); pcm.writeUInt16LE(16, 34);
pcm.write('data', 36); pcm.writeUInt32LE(N * 4, 40);
for (let i = 0; i < N; i++) {
  pcm.writeInt16LE(Math.round(L[i] * gain * 32767), 44 + i * 4);
  pcm.writeInt16LE(Math.round(R[i] * gain * 32767), 46 + i * 4);
}
writeFileSync(out, pcm);
process.stdout.write(`✓ ${out} (${TOTAL}s, ${BPM} BPM, ${CUTS.length} cuts)\n`);
